const softDeleteItemsOfRootWithoutOtherFiles = `-- name: SoftDeleteItemsOfRootWithoutOtherFiles :execrows

UPDATE items SET deleted_at = ?1, updated_at = ?1
WHERE items.deleted_at IS NULL
  AND (items.kind IN ('movie', 'episode', 'extra', 'audiobook') OR (items.kind = 'podcast_episode' AND items.enclosure_url IS NULL))
  AND EXISTS (SELECT 1 FROM media_files AS m WHERE m.item_id = items.id AND m.root_id = ?2)
  AND NOT EXISTS (SELECT 1 FROM media_files AS m WHERE m.item_id = items.id AND m.root_id <> ?2)
`

type SoftDeleteItemsOfRootWithoutOtherFilesParams struct {
	Now    sql.NullInt64
	RootID int64
}

// Removing a folder from a library (idea 02, E12). The order of the three queries is not taste:
// media_files.root_id cascades on delete, so a title left without any file would never be seen
// by SoftDeleteItemsMissingSince again (it requires EXISTS (SELECT 1 FROM media_files ...)), and
// downloads.media_file_id cascades too, so a surviving title would lose its download.
// Titles that live only in this folder leave the library at once. Unlike
// SoftDeleteItemWithoutFiles this carries 'audiobook': an audiobook library would keep empty
// rows behind otherwise. "Another folder" means any other registered folder, not only one of
// the same library: folders may not overlap, so the two coincide, except for a title that was
// given a file of another library by AdminMoveMediaFiles while merging. Keeping that title is
// the safe reading -- it still has a file to play.
func (q *Queries) SoftDeleteItemsOfRootWithoutOtherFiles(ctx context.Context, arg SoftDeleteItemsOfRootWithoutOtherFilesParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, softDeleteItemsOfRootWithoutOtherFiles, arg.Now, arg.RootID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const trickplayJobEnded = `-- name: TrickplayJobEnded :one
SELECT EXISTS (
    SELECT 1 FROM jobs
    WHERE type = 'trickplay.generate' AND state IN ('done', 'failed', 'cancelled') AND idempotency_key = ?1
)
`

// Whether a run of trickplay.generate under @idempotency_key ended (done, failed or cancelled): with
// no active job and no complete set, the set of the file ended without being made (state failed).
func (q *Queries) TrickplayJobEnded(ctx context.Context, idempotencyKey sql.NullString) (bool, error) {
	row := q.db.QueryRowContext(ctx, trickplayJobEnded, idempotencyKey)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const updateItemsProvidersByRoot = `-- name: UpdateItemsProvidersByRoot :execrows
UPDATE items SET providers = ?1, updated_at = ?2
WHERE deleted_at IS NULL AND (
    id IN (SELECT m.item_id FROM media_files AS m WHERE m.root_id = ?3)
    OR id IN (SELECT i.parent_id FROM media_files AS m JOIN items AS i ON i.id = m.item_id WHERE m.root_id = ?3)
    OR id IN (SELECT p.parent_id FROM media_files AS m JOIN items AS i ON i.id = m.item_id
              JOIN items AS p ON p.id = i.parent_id WHERE m.root_id = ?3)
    OR parent_id IN (SELECT i.parent_id FROM media_files AS m JOIN items AS i ON i.id = m.item_id WHERE m.root_id = ?3)
    OR parent_id IN (SELECT p.parent_id FROM media_files AS m JOIN items AS i ON i.id = m.item_id
                     JOIN items AS p ON p.id = i.parent_id WHERE m.root_id = ?3)
    OR parent_id IN (SELECT c.id FROM items AS c WHERE c.parent_id IN (
                         SELECT p.parent_id FROM media_files AS m JOIN items AS i ON i.id = m.item_id
                         JOIN items AS p ON p.id = i.parent_id WHERE m.root_id = ?3)))
`

type UpdateItemsProvidersByRootParams struct {
	Providers string
	Now       int64
	RootID    int64
}

// The new list of a folder on every title with a file in it, its ancestors and the descendants of
// those ancestors: a series with all its seasons and episodes, a movie with its extras. The tree
// is three levels deep at most (series, season, episode), so the ancestors are the parent and the
// grandparent, the descendants the children and the grandchildren of what those name.
func (q *Queries) UpdateItemsProvidersByRoot(ctx context.Context, arg UpdateItemsProvidersByRootParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateItemsProvidersByRoot, arg.Providers, arg.Now, arg.RootID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateMediaFileProbeError = `-- name: UpdateMediaFileProbeError :execrows
UPDATE media_files SET probe_error = ?1, probed_at = ?2, updated_at = ?2
WHERE id = ?3 AND size = ?4 AND mtime = ?5
`

type UpdateMediaFileProbeErrorParams struct {
	ProbeError sql.NullString
	Now        sql.NullInt64
	ID         string
	Size       int64
	Mtime      int64
}

// ffprobe failed on the file (B-9 "unplayable"): the attempt is recorded, the stream columns stay.
// Only for the version (size, mtime) the probe read, like UpdateMediaFileProbe: 0 rows means the
// file changed meanwhile, and probe.file runs again on the new version (concept 14, Z-9).
func (q *Queries) UpdateMediaFileProbeError(ctx context.Context, arg UpdateMediaFileProbeErrorParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateMediaFileProbeError,
		arg.ProbeError,
		arg.Now,
		arg.ID,
		arg.Size,
		arg.Mtime,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
